static ssize_t target_lu_gp_members_show(struct config_item *item, char *page)
{
	struct target_fabric_configfs_hba_group *hba;
	struct target_fabric_configfs_dev *dev;
	int i, len, cur_len = 0;

	if (!item || !page)
		return -EINVAL;

	hba = container_of(item, struct target_fabric_configfs_hba_group, cg_item);

	mutex_lock(&hba->hba_group_lock);
	for (i = 0; i < hba->hba_dev_count; i++)
	{
		dev = hba->hba_devs[i];
		len = snprintf(page + cur_len, PAGE_SIZE - cur_len - 1,
				"%s/%s\n",
				config_item_name(&hba->hba_group.cg_item),
				config_item_name(&dev->dev_group.cg_item));
		cur_len++; /* Extra byte for NULL terminator */

		if ((cur_len + len) > PAGE_SIZE) {
			pr_warn("Ran out of lu_gp_show_attr"
				"_members buffer\n");
			break;
		}
	}
	mutex_unlock(&hba->hba_group_lock);

	return cur_len;
}
